from concurrent.futures import ThreadPoolExecutor
import pytest


def square(x: int) -> int:
    """Return the square of an integer."""
    return x * x


def sum_squares(xs: list[int], max_workers: int | None = None) -> int:
    """Sum the squares of every element using a thread pool."""
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        return sum(executor.map(square, xs))


def test_square() -> None:
    assert square(0) == 0
    assert square(3) == 9
    assert square(-4) == 16


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([5]) == 25
    assert sum_squares([-3]) == 9


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([-1, 0, 1, 2]) == 6


def test_sum_squares_worker_counts() -> None:
    xs = list(range(-20, 21))
    expected = sum(x * x for x in xs)
    for workers in (1, 2, 4, 8, 16):
        assert sum_squares(xs, max_workers=workers) == expected

